.version 8.0
.target sm_89
.address_size 64

.visible .entry matmul_tall_skinny_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K,
    .param .u32 N
)
