    .reg .pred p0, p1;
    .reg .b32 rM, rK, rN, ri, rj, rk;
    .reg .b32 rtid_x, rtid_y, rctaid_x, rctaid_y, rntid_x, rntid_y;
    .reg .b64 rA, rB, rC, addrA, addrB, addrC, idx64, tmp64a, tmp64b, rk64, rj64;
    .reg .f32 fa, fb, facc;

